import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, nowIso } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const json = (res: ServerResponse, status: number, body: unknown): void => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
};
const error = (res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void => {
  json(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
};
async function bodyOf(req: IncomingMessage): Promise<string> {
  let body = ''; for await (const chunk of req) { body += chunk.toString(); if (body.length > 100_000) throw new Error('too_large'); }
  return body;
}
function fieldErrors(value: unknown): { input: string; steps: number; failAttempts: number } | { field: string; message: string }[] {
  const fields: {field:string;message:string}[] = [];
  if (!value || typeof value !== 'object' || Array.isArray(value)) return [{ field: 'body', message: 'Must be a JSON object.' }];
  const obj = value as Record<string, unknown>;
  for (const key of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else {
    if (obj.input.length < 1 || obj.input.length > 1000) fields.push({ field: 'input', message: 'Must be 1–1000 characters.' });
    if (!obj.input.trim()) fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }
  const steps = obj.steps === undefined ? 5 : obj.steps;
  const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  return fields.length ? fields : { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number };
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') { res.writeHead(200, { 'content-type':'text/html; charset=utf-8' }); res.end(uiHtml); return; }
  if (pathname === '/health' && req.method === 'GET') {
    const beat = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as {at:number} | undefined;
    json(res, 200, { status: 'ok', worker: beat && Date.now() - beat.at < 3000 ? 'up' : 'down' }); return;
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string,unknown>[];
    json(res, 200, { jobs: rows.map(toJob) }); return;
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) { error(res,400,'invalid_request','Request must use application/json.',[{field:'body',message:'Content-Type must be application/json.'}]); return; }
    let bodyText: string;
    try { bodyText = await bodyOf(req); } catch { error(res,400,'invalid_request','Invalid request body.',[{field:'body',message:'Body is too large or unreadable.'}]); return; }
    let parsed: unknown;
    try { parsed = JSON.parse(bodyText); } catch { error(res,400,'invalid_request','Malformed JSON.',[{field:'body',message:'Must be valid JSON.'}]); return; }
    const validated = fieldErrors(parsed);
    if (Array.isArray(validated)) { error(res,400,'invalid_request','Request validation failed.',validated); return; }
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) {
      error(res,400,'invalid_request','Request validation failed.',[{field:'Idempotency-Key',message:'Must match ^[A-Za-z0-9_-]{1,128}$.'}]); return;
    }
    const payload = JSON.stringify(validated);
    try {
      db.exec('BEGIN IMMEDIATE');
      if (key) {
        const prior = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(key) as Record<string,unknown> | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) error(res,409,'idempotency_conflict','This Idempotency-Key was used with a different payload.');
          else json(res,200,toJob(prior));
          return;
        }
      }
      const id = randomUUID(), now = nowIso();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,idempotency_key,payload,available_at)
        VALUES(?,?,?,?,?,0,0,NULL,NULL,?,?,?, ?,0)`).run(id,'queued',validated.input,validated.steps,validated.failAttempts,now,now,key ?? null,payload);
      const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string,unknown>;
      db.exec('COMMIT'); json(res,201,toJob(row));
    } catch (e) { try { db.exec('ROLLBACK'); } catch {} error(res,500,'internal_error','Unable to save job.'); }
    return;
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match && req.method === 'GET') {
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { error(res,404,'not_found','Job not found.'); return; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string,unknown> | undefined;
    if (!row) error(res,404,'not_found','Job not found.'); else json(res,200,toJob(row)); return;
  }
  if (pathname === '/api/jobs' || pathname.startsWith('/api/jobs/')) { error(res,405,'method_not_allowed','Method not allowed.'); return; }
  if (pathname === '/' || pathname === '/health') { error(res,405,'method_not_allowed','Method not allowed.'); return; }
  error(res,404,'not_found','Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
const shutdown = () => { server.close(() => { db.close(); }); };
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer owns it. Requeue it at startup;
// attempts already counts that interrupted attempt, so retry limits remain durable.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=0 WHERE status='running'").run(nowIso());
const heartbeat = db.prepare('INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at');
const getNext = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1");
const claim = db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, error=NULL, updated_at=? WHERE id=? AND status='queued'");
const updateProgress = db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running' AND attempts=?");
const finish = db.prepare("UPDATE jobs SET status='completed', result_output=?, progress_completed=steps, error=NULL, updated_at=? WHERE id=? AND status='running' AND attempts=?");
const retry = db.prepare("UPDATE jobs SET status='queued', progress_completed=0, error=NULL, available_at=?, updated_at=? WHERE id=? AND status='running' AND attempts=?");
const fail = db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running' AND attempts=?");

while (!stopping) {
  heartbeat.run(Date.now());
  const row = getNext.get(Date.now()) as {id:string; input:string; steps:number; fail_attempts:number; attempts:number} | undefined;
  if (!row) { await sleep(100); continue; }
  const nextAttempt = Number(row.attempts) + 1;
  db.exec('BEGIN IMMEDIATE');
  try { claim.run(nowIso(), row.id); db.exec('COMMIT'); } catch (e) { db.exec('ROLLBACK'); continue; }
  if (nextAttempt <= Number(row.fail_attempts)) {
    if (nextAttempt >= 3) fail.run(nowIso(), row.id, nextAttempt);
    else retry.run(Date.now() + 500, nowIso(), row.id, nextAttempt);
    continue;
  }
  let interrupted = false;
  for (let step = 1; step <= Number(row.steps); step++) {
    await sleep(100);
    if (stopping) { interrupted = true; break; }
    updateProgress.run(step, nowIso(), row.id, nextAttempt);
  }
  if (!interrupted) finish.run(row.input.toUpperCase(), nowIso(), row.id, nextAttempt);
}
db.close();
